use std::{fs::read_to_string, io::Error as IoError, path::PathBuf};
use thiserror::Error;

use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct FetcherConfig {
    /// Size of API batches
    pub batch_size: u8,
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for FetcherConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct LoaderConfig {
    /// Database connection string
    pub connection_string: String,
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for LoaderConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Error, Debug)]
/// Collection of errors when parsing configuration
pub enum CliConfigError {
    #[error("yaml malformatted")]
    /// Yaml cannot be parsed
    FormattingError(#[from] rust_yaml::Error),
    #[error("unable to read config")]
    /// Config path invalid
    FileNotFound(#[from] IoError),
}
//! Integration test for the entity seacrh endpoint.
//! This test suite expects a pre-loaded database.
//!
//!

use std::{collections::HashMap, ffi::OsString, time::Duration};

use clap::Parser;
use exposed::{
    domain::{
        models::{entity_ingestion::IngestionKey, entity_search::EntitySearchRequest},
        repositories::parliament_member_repository::ParliamentMemberRepo,
    },
    inbound::cli::{DataArgs, run_cli},
    outbound::ExposedDatabase,
};
use sqlx::{ConnectOptions, PgPool};
use tempfile::TempDir;
use tokio::time;

use crate::common::{cli_fetcher_config, cli_loader_config, search_entities, start_app};

mod common;

#[tokio::test]
async fn shows_no_hsbc_duplicates() {
    let _guard = start_app().await.unwrap();
    time::sleep(Duration::from_secs(2)).await;

    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
    let entities = search_entities(&known_duplicate).await.unwrap();

    let mut duplicates: HashMap<String, usize> = HashMap::new();
    for e in entities.into_iter() {
        duplicates
            .entry(e.get("name").unwrap().as_str().unwrap().into())
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
}

#[sqlx::test(migrations = "../db/migrations")]
async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new().unwrap();

    let (_file, path) = cli_fetcher_config(&tmp);
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "fetch".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_loader_config(&tmp, url.to_string().as_str());
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "load".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let db = ExposedDatabase::from(pool);

    let params =
        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
    let res = db.get_members_by_text_search_score(&params).await.unwrap();

    let (mp, _) = res.first().unwrap();
    assert_eq!(mp.name(), "John McDonnell".to_string());

    Ok(())
}
use std::{fs::File, io::Write, path::PathBuf, str::FromStr};

use exposed::{
    domain::models::entity_search::EntitySearchRequest,
    inbound::{
        cli::config::{FetcherConfig, LoaderConfig},
        http::{config::ServerConfig, server::serve_exposed},
    },
};
use reqwest::StatusCode;
use serde_json::Value;
use tempfile::{NamedTempFile, TempDir};

pub struct Guard;

pub async fn search_entities(params: &EntitySearchRequest) -> anyhow::Result<Vec<Value>> {
    let client = reqwest::Client::new();

    let test_config = PathBuf::from_str("config/server-test.yaml").unwrap();
    let config = ServerConfig::try_from(&test_config).unwrap();
    let port = config.port;

    let (term, strictness, entries) = (params.term(), params.strictness(), params.max_entries());
    let url = format!(
        "http://127.0.0.1:{port}/search?term={term}&&strictness={strictness}&&max_entries={entries}"
    );
    let response = client.get(url).send().await?;

    match response.status() {
        StatusCode::OK => {
            let bytes = response.bytes().await?;
            let data: Value = serde_json::from_slice(&bytes)?;
            let entities = data
                .get("entities")
                .and_then(|d| d.as_array())
                .ok_or(anyhow::anyhow!("unparsable"))?
                .to_vec();
            Ok(entities)
        }
        StatusCode::INTERNAL_SERVER_ERROR => Err(anyhow::anyhow!("something unexpected happened")),
        StatusCode::UNPROCESSABLE_ENTITY => Err(anyhow::anyhow!("bad url")),
        _ => Err(anyhow::anyhow!(
            "something really unexpected happened, investigate"
        )),
    }
}

pub async fn start_app() -> anyhow::Result<Guard> {
    let _handle = tokio::task::spawn(async move {
        let test_config = PathBuf::from_str("config/server-test.yaml").unwrap();
        let config = ServerConfig::try_from(&test_config).unwrap();
        let _ = serve_exposed(&config).await;
        println!("started");
    });

    Ok(Guard)
}

pub fn cli_fetcher_config(tmp: &TempDir) -> (NamedTempFile<File>, PathBuf) {
    let config = FetcherConfig {
        batch_size: 100,
        data_dir: tmp.path().to_path_buf(),
    };
    let contents = rust_yaml::to_string(&config).unwrap();
    let mut file = tempfile::NamedTempFile::new().unwrap();
    file.write_all(contents.as_bytes()).unwrap();
    let path = file.path().to_path_buf();
    (file, path)
}

pub fn cli_loader_config(tmp: &TempDir, conn_str: &str) -> (NamedTempFile<File>, PathBuf) {
    let config = LoaderConfig {
        connection_string: conn_str.to_string(),
        data_dir: tmp.path().to_path_buf(),
    };
    let contents = rust_yaml::to_string(&config).unwrap();
    let mut file = tempfile::NamedTempFile::new().unwrap();
    file.write_all(contents.as_bytes()).unwrap();
    let path = file.path().to_path_buf();
    (file, path)
}

