//! Contains entity ingestion models

use std::{fmt::Display, str::FromStr};

// use std::str::FromStr;
//
use strum::EnumString;
use thiserror::Error;
use uuid::Uuid;

use crate::domain::repositories::{
    entity_ingestion::EntitySearchPipelineError, parliament_api::ParliamentApiError,
};

/// Data required to search entities
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EntityIngestionRequest;

/// Key used for ingestion
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct IngestionKey(Uuid);

impl Display for IngestionKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.0.to_string().as_str())
    }
}

impl FromStr for IngestionKey {
    type Err = EntityIngestionError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let id =
            Uuid::from_str(s).map_err(|e| EntityIngestionError::InvalidStage(e.to_string()))?;
        Ok(Self(id))
    }
}

impl IngestionKey {
    /// Creates a new key
    #[must_use]
    pub const fn new(uuid: Uuid) -> Self {
        Self(uuid)
    }

    /// Underlying UUID
    #[must_use]
    pub const fn uuid(&self) -> Uuid {
        self.0
    }
}

impl Default for IngestionKey {
    fn default() -> Self {
        Self::new(Uuid::now_v7())
    }
}

/// From what stage to run in the Member pipeline
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum MemberIngestionStage {
    Fetch,
    Load,
}
//
// /// From what stage to run the declaration pipeline
// #[derive(Clone, Debug, PartialEq, Eq, EnumString)]
// #[allow(missing_docs)]
// #[strum(ascii_case_insensitive)]
// pub enum DeclarationIngestionStage {
//     Fetch,
//     Clean,
//     Resolve,
//     Load,
// }
//
/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    IoError(#[from] EntitySearchPipelineError),

    /// Invalid stage
    #[error("invalid stage provided: {0}")]
    InvalidStage(String),

    /// Invalid stage
    #[error("invalid ingestion ID: {0}")]
    UnvalidIngestionId(String),

    /// Generic error
    #[error("unexpected error occured: {0}")]
    UnexpectedError(String),
}
use thiserror::Error;

use crate::domain::models::{entity_ingestion::IngestionKey, parliament_member::ParliamentMember};

/// Set of I/O methods for data in the entity search pipeline
pub trait EntityIngestionStorage: Clone + Send + Sync + 'static {
    /// Key used for storage
    fn ingestion_key(&self) -> IngestionKey;
    /// Reads raw data persisted from the parliament API    
    fn read_raw_members(
        &self,
    ) -> impl Future<Output = Result<Vec<ParliamentMember>, EntitySearchPipelineError>> + Send;
    /// Reads cleaned data
    fn read_cleaned_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Reads resolved data
    fn read_resolved_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes raw data pulled from the parliament API
    fn write_raw_members(
        &self,
        members: &[ParliamentMember],
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes cleaned data pulled from the parliament API
    fn write_cleaned_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes resolved data pulled from the parliament API
    fn write_resolved_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
}

/// Errors that can occur when interacting with the repo
#[derive(Error, Debug)]
pub enum EntitySearchPipelineError {
    /// Generic error when something unexpected goes wrong
    #[error("unexpected error occured: {0}")]
    Unexpected(String),
    /// Error when reading pipeline results
    #[error("unable to read pipeline data due to {0}")]
    ReadError(String),
    /// Error when writing pipeline results
    #[error("unable to write pipeline data due to {0}")]
    WriteError(String),
}
use thiserror::Error;

use crate::domain::models::parliament_member::ParliamentMember;

/// Allows users to interact with the UK Parliament API.
pub trait ParliamentApi: Clone + Send + Sync + 'static {
    /// Returns members sitting in the current parliament
    fn get_sitting_members(
        &self,
    ) -> impl Future<Output = Result<Vec<ParliamentMember>, ParliamentApiError>> + Send;
    /// Returns declarations for sitting members
    fn get_declarations_for_sitting_members(
        &self,
    ) -> impl Future<Output = Result<(), ParliamentApiError>> + Send;
}

/// Errors that can occur when interacting with the repo
#[derive(Error, Debug)]
pub enum ParliamentApiError {
    /// Generic error from the database
    #[error("unable to get API results due to {0}")]
    ApiError(String),
}
//! Service for ingesting entity search data
//!

use crate::domain::{
    models::entity_ingestion::{EntityIngestionError, EntityIngestionRequest, IngestionKey},
    repositories::{
        entity_ingestion::EntityIngestionStorage, parliament_api::ParliamentApi,
        parliament_member_repository::ParliamentMemberRepo,
    },
};

mod error;
mod interface;

pub use interface::EntityFetcherService;
pub use interface::EntityIngesterService;

/// Allows users to search the databse using free text.
#[derive(Clone)]
pub struct FetcherService<PS, PA> {
    pipeline_storage: PS,
    parliament_api: PA,
}

impl<PS, PA> FetcherService<PS, PA> {
    /// Creates a new instance
    pub const fn new(pipeline_storage: PS, parliament_api: PA) -> Self {
        Self {
            pipeline_storage,
            parliament_api,
        }
    }
}

impl<PS, PA> EntityFetcherService for FetcherService<PS, PA>
where
    PS: EntityIngestionStorage,
    PA: ParliamentApi,
{
    async fn fetch_members(
