    let _handle = tokio::task::spawn(async move {
        let test_config = PathBuf::from_str("config/server-test.yaml").unwrap();
        let config = ServerConfig::try_from(&test_config).unwrap();
        let _ = serve_exposed(&config).await;
        println!("started");
    });

    Ok(Guard)
}

