    };
    Ok(SourceFieldGroup::new(
        path.to_string(),
        text("UltimatePayerName")?,
        donor_name,
        text("PayerName")?,
        amount,
        currency,
        text("PaymentType")?,
        text("DonorStatus")?,
        text("DonorCompanyIdentifier")?,
