    assert_eq!(bob.path(), "/versions/0/fields/4/values/2");
    assert_eq!(bob.donor_name(), Some("Bob Example"));
    assert_eq!(bob.amount(), Some("300.00"));
    assert_eq!(bob.currency(), Some("GBP"));
    assert_eq!(bob.payment_type(), Some("In kind"));
