struct InterestPage {
    skip: usize,
    take: usize,
    total_results: usize,
    items: Vec<Box<RawValue>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Interest {
    id: u32,
    parent_interest_id: Option<u32>,
    category: Category,
    registrant: Registrant,
    versions: Vec<Version>,
}

#[derive(Deserialize)]
struct Category {
    id: u32,
    name: String,
    r#type: String,
}

#[derive(Deserialize)]
