//! Deserialize and project the Interests API response.

use chrono::{DateTime, NaiveDate, Utc};
use serde::Deserialize;
use serde_json::Value;

use super::{ApiError, ParliamentApiClient};
use crate::domain::models::declaration_ingestion::{
    CapturedDeclaration, CapturedVersion, DeclarationId, SourceFieldGroup, StoredMember,
};

const INTERESTS_URL: &str = "https://interests-api.parliament.uk/api/v2/Interests";

#[cfg(test)]
mod tests;

impl ParliamentApiClient {
    pub(super) async fn capture_declarations(
        &self,
        member: StoredMember,
    ) -> Result<Vec<CapturedDeclaration>, ApiError> {
        let mut declarations = Vec::new();
        let mut offset = 0;
        loop {
            let url = format!(
                "{INTERESTS_URL}?MemberId={}&Type=Commons&ExcludeExpired=false&ExpandChildInterests=false&Skip={offset}&Take={}",
                member.parliament_member_id(),
                self.batch_size,
            );
            let bytes = self.client.get(url).send().await?.bytes().await?;
            let response: InterestPage = serde_json::from_slice(&bytes)?;
            if response.items.is_empty() {
                break;
            }
            let fetched_at = Utc::now();
            offset += response.items.len();
            for source in response.items {
                declarations.push(decode_declaration(source, fetched_at)?);
            }
            if offset >= response.total_results {
                break;
            }
        }
        Ok(declarations)
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct InterestPage {
    total_results: usize,
    // Retain every source field alongside the typed projection below.
    items: Vec<Value>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Interest {
    id: u32,
    parent_interest_id: Option<u32>,
    category: Category,
    versions: Vec<Version>,
}

#[derive(Deserialize)]
struct Category {
    id: u32,
    name: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Version {
    register: Register,
    registration_date: Option<NaiveDate>,
    fields: Option<Vec<SourceField>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Register {
    id: u32,
    published_date: NaiveDate,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SourceField {
    name: String,
    #[serde(default)]
    value: Value,
    type_info: Option<Currency>,
    values: Option<Vec<Vec<Self>>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Currency {
    currency_code: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct FundingFields {
    ultimate_payer_name: Option<String>,
    donor_name: Option<String>,
    name: Option<String>,
    payer_name: Option<String>,
    value: Option<Amount>,
    payment_type: Option<String>,
    donor_status: Option<String>,
    donor_company_identifier: Option<String>,
    is_ultimate_payer_different: Option<bool>,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum Amount {
    Text(String),
    Number(serde_json::Number),
}

impl Amount {
    fn into_text(self) -> String {
        match self {
            Self::Text(value) => value,
            Self::Number(value) => value.to_string(),
        }
    }
}

fn decode_declaration(
    source: Value,
    fetched_at: DateTime<Utc>,
) -> Result<CapturedDeclaration, ApiError> {
    let source_json = source.to_string();
    let source: Interest = serde_json::from_value(source)?;
    let versions = (0..)
        .zip(source.versions)
        .map(|(index, version)| {
            let path = format!("/versions/{index}/fields");
            let fields = version.fields.unwrap_or_default();
            let mut groups = vec![project_group(&fields, &path, false)?];
            donor_groups(&fields, &path, &mut groups)?;
            Ok(CapturedVersion::new(
                index,
                version.register.id,
                version.register.published_date,
                version.registration_date,
                groups,
            )?)
        })
        .collect::<Result<Vec<_>, ApiError>>()?;
    Ok(CapturedDeclaration::new(
        DeclarationId::new(source.id)?,
        source
            .parent_interest_id
            .map(DeclarationId::new)
            .transpose()?,
        source.category.id,
        source.category.name,
        versions,
        fetched_at,
        source_json,
    )?)
}

fn donor_groups(
    fields: &[SourceField],
    path: &str,
    groups: &mut Vec<SourceFieldGroup>,
) -> Result<(), ApiError> {
    for (field_index, field) in fields.iter().enumerate() {
        for (group_index, nested) in field.values.iter().flatten().enumerate() {
            let path = format!("{path}/{field_index}/values/{group_index}");
            if field.name == "Donors" {
                groups.push(project_group(nested, &path, true)?);
            }
            donor_groups(nested, &path, groups)?;
        }
    }
    Ok(())
}

fn project_group(
    fields: &[SourceField],
    path: &str,
    donor: bool,
) -> Result<SourceFieldGroup, ApiError> {
    let values = fields
        .iter()
        .map(|field| (field.name.clone(), field.value.clone()))
        .collect();
    let funding: FundingFields = serde_json::from_value(Value::Object(values))?;
    let currency = fields
        .iter()
        .find(|field| field.name == "Value")
        .and_then(|field| field.type_info.as_ref())
        .and_then(|info| info.currency_code.clone());
    let donor_name = funding
        .donor_name
        .or(if donor { funding.name } else { None });
    Ok(SourceFieldGroup::new(
        path.to_string(),
        funding.ultimate_payer_name,
        donor_name,
        funding.payer_name,
        funding.value.map(Amount::into_text),
        currency,
        funding.payment_type,
        funding.donor_status,
        funding.donor_company_identifier,
        funding.is_ultimate_payer_different,
    ))
}
//! Integration test for the entity seacrh endpoint.
//! This test suite expects a pre-loaded database.
//!
//!

use std::{collections::HashMap, ffi::OsString, time::Duration};

use anyhow::Context;
use clap::Parser;
use exposed::{
    domain::{
        models::{entity_ingestion::IngestionKey, entity_search::EntitySearchRequest},
        repositories::parliament_member_repository::ParliamentMemberRepo,
    },
    inbound::cli::{DataArgs, run_cli},
    outbound::ExposedDatabase,
};
use sqlx::{ConnectOptions, PgPool};
use tempfile::TempDir;
use tokio::time;

use crate::common::{
    DeclarationFunding, cli_declaration_fetcher_config, cli_fetcher_config, cli_loader_config,
    read_declaration_funding, search_entities, start_app,
};

mod common;

#[tokio::test]
async fn shows_no_hsbc_duplicates() {
    let _guard = start_app().await.unwrap();
    time::sleep(Duration::from_secs(2)).await;

    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
    let entities = search_entities(&known_duplicate).await.unwrap();

    let mut duplicates: HashMap<String, usize> = HashMap::new();
    for e in entities.into_iter() {
        duplicates
            .entry(e.get("name").unwrap().as_str().unwrap().into())
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
}

#[sqlx::test(migrations = "../db/migrations")]
async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new().unwrap();

    let (_file, path) = cli_fetcher_config(&tmp);
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "fetch".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_loader_config(&tmp, url.to_string().as_str());
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "load".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let url = pool.connect_options().to_url_lossy();
    let db = ExposedDatabase::new(url.as_str()).await;

    let params =
        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
    let res = db.get_members_by_text_search_score(&params).await.unwrap();

    let (mp, _) = res.first().unwrap();
    assert_eq!(mp.name(), "John McDonnell".to_string());

    Ok(())
}

#[sqlx::test(migrations = "../db/migrations")]
async fn declaration_fetch_preserves_member_funding(pool: PgPool) -> anyhow::Result<()> {
    let members = sqlx::query!(
        "INSERT INTO exposed.members
            (parliament_member_id, name, party_id, party_name, latest_house,
             latest_membership_from, is_current_commons)
         VALUES (4613, 'Alex Burghart', 4, 'Conservative', 1, 'Brentwood and Ongar', true),
                (5030, 'Dr Simon Opher', 15, 'Labour', 1, 'Stroud', true)
         RETURNING id, parliament_member_id"
    )
    .fetch_all(&pool)
    .await?
    .into_iter()
    .map(|member| (member.parliament_member_id, member.id))
    .collect::<HashMap<_, _>>();
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new()?;
    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_declaration_fetcher_config(&tmp, url.as_str());
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "declarations".into(),
        "fetch".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])?;

    run_cli(args).await?;
    let funding = read_declaration_funding(tmp.path(), &ingestion_key)?;

    let individual_donation = funding
        .iter()
        .find(|entry| entry.declaration_id == 16901)
        .context("expected Alex Burghart's donation from David Robert Meller")?;
    assert_eq!(
        individual_donation,
        &DeclarationFunding {
            declaration_id: 16901,
            member_id: members[&4613].to_string(),
            donor_name: Some("David Robert Meller".into()),
            amount: Some("2000.00".into()),
            currency: Some("GBP".into()),
            payment_type: Some("Monetary".into()),
            funder_kind: Some("Individual".into()),
            company_number: None,
        }
    );

    let company_donation = funding
        .iter()
        .find(|entry| entry.declaration_id == 16863)
        .context("expected Simon Opher's donation from Labour Together")?;
    assert_eq!(
        company_donation,
        &DeclarationFunding {
            declaration_id: 16863,
            member_id: members[&5030].to_string(),
            donor_name: Some("Labour Together Limited".into()),
            amount: Some("5000.00".into()),
            currency: Some("GBP".into()),
            payment_type: Some("Monetary".into()),
            funder_kind: Some("Company".into()),
            company_number: Some("09630980".into()),
        }
    );
    Ok(())
}

