use std::fs::{self, File};

use arrow::{
    array::AsArray,
    datatypes::{DataType, TimeUnit},
};
use chrono::{NaiveDate, Utc};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde_json::{Value, json};
use tempfile::TempDir;
use uuid::Uuid;

use super::{ExposedDataPipeline, member_filename};
use crate::domain::{
    models::{
        declaration_ingestion::{
            CapturedDeclaration, CapturedVersion, DeclarationId, DeclarationMemberOutput,
            SourceFieldGroup, StoredMember,
        },
        entity_ingestion::IngestionKey,
    },
    repositories::entity_ingestion::EntityIngestionStorage,
};

#[tokio::test]
async fn publishes_empty_member_partitions_and_completion_counts() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let key = IngestionKey::default();
    let storage =
        ExposedDataPipeline::new_with_ingestion_key(&tmp.path().to_path_buf(), key.clone())?;
    let member = StoredMember::new(Uuid::from_u128(1), 512)?;
    let directory = storage.declarations_path();

    storage.begin_declarations().await?;
    storage.write_raw_declarations(member, &[]).await?;

    assert!(!directory.join("manifest.json").exists());
    let reader = ParquetRecordBatchReaderBuilder::try_new(File::open(
        directory.join(member_filename(member)),
    )?)?;
    let schema = reader.schema();
    assert_eq!(
        schema.field_with_name("registration_date")?.data_type(),
        &DataType::Date32
    );
    assert_eq!(
        schema.field_with_name("fetched_at")?.data_type(),
        &DataType::Timestamp(TimeUnit::Microsecond, Some("UTC".into()))
    );
    assert_eq!(
        schema.field_with_name("source_json")?.data_type(),
        &DataType::Utf8
    );
    assert_eq!(reader.build()?.count(), 0);

    storage
        .complete_declarations(&[DeclarationMemberOutput::new(member, 0, 0)])
        .await?;

    let manifest: Value = serde_json::from_slice(&fs::read(directory.join("manifest.json"))?)?;
    assert_eq!(manifest["ingestion_key"], key.to_string());
    assert_eq!(manifest["member_count"], 1);
    assert_eq!(manifest["declaration_count"], 0);
    assert_eq!(manifest["row_count"], 0);
    assert_eq!(
        manifest["members"],
        json!([{
            "member_id": member.member_id().to_string(),
            "parliament_member_id": 512,
            "file": format!("{}.parquet", member.member_id()),
            "declaration_count": 0,
            "row_count": 0
        }])
    );
    Ok(())
}

#[tokio::test]
async fn protects_existing_partitions_and_completed_or_incomplete_runs() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let storage = ExposedDataPipeline::new_with_ingestion_key(
        &tmp.path().to_path_buf(),
        IngestionKey::default(),
    )?;
    let member = StoredMember::new(Uuid::from_u128(1), 512)?;
    let directory = storage.declarations_path();
    let manifest_path = directory.join("manifest.json");
    let partition_path = directory.join(member_filename(member));

    storage.begin_declarations().await?;
    storage.write_raw_declarations(member, &[]).await?;
    let original_partition = fs::read(&partition_path)?;

    assert!(storage.begin_declarations().await.is_err());
    assert!(storage.write_raw_declarations(member, &[]).await.is_err());
    assert_eq!(fs::read(&partition_path)?, original_partition);
    assert!(!manifest_path.exists());

    let outputs = [DeclarationMemberOutput::new(member, 0, 0)];
    storage.complete_declarations(&outputs).await?;
    let original_manifest = fs::read(&manifest_path)?;

    assert!(storage.begin_declarations().await.is_err());
    assert!(storage.complete_declarations(&outputs).await.is_err());
    assert_eq!(fs::read(&manifest_path)?, original_manifest);
    assert_eq!(fs::read(&partition_path)?, original_partition);
    Ok(())
}

#[tokio::test]
async fn saves_the_same_declaration_for_each_declaring_member() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let storage = ExposedDataPipeline::new_with_ingestion_key(
        &tmp.path().to_path_buf(),
        IngestionKey::default(),
    )?;
    let members = [
        StoredMember::new(Uuid::from_u128(1), 4613)?,
        StoredMember::new(Uuid::from_u128(2), 5030)?,
    ];
    let declaration = CapturedDeclaration::new(
        DeclarationId::new(42)?,
        None,
        3,
        "Donations".into(),
        vec![CapturedVersion::new(
            0,
            820,
            NaiveDate::from_ymd_opt(2026, 9, 7).unwrap(),
            None,
            vec![SourceFieldGroup::new(
                "/versions/0/fields".into(),
                None,
                Some("Shared donor".into()),
                None,
                Some("2000.00".into()),
                Some("GBP".into()),
                None,
                None,
                None,
                None,
            )],
        )?],
        Utc::now(),
        r#"{"id":42}"#.into(),
    )?;

    storage.begin_declarations().await?;
    for member in members {
        storage
            .write_raw_declarations(member, std::slice::from_ref(&declaration))
            .await?;
        let file = File::open(storage.declarations_path().join(member_filename(member)))?;
        let mut reader = ParquetRecordBatchReaderBuilder::try_new(file)?.build()?;
        let row = reader.next().unwrap()?;
        let member_ids = row.column_by_name("member_id").unwrap().as_string::<i32>();
        let declaration_ids = row
            .column_by_name("declaration_id")
            .unwrap()
            .as_primitive::<arrow::datatypes::UInt32Type>();

        assert_eq!(row.num_rows(), 1);
        assert_eq!(member_ids.value(0), member.member_id().to_string());
        assert_eq!(declaration_ids.value(0), 42);
        assert!(reader.next().is_none());
    }
    let outputs = members.map(|member| DeclarationMemberOutput::new(member, 1, 1));
    storage.complete_declarations(&outputs).await?;
    let manifest: Value = serde_json::from_slice(&fs::read(
        storage.declarations_path().join("manifest.json"),
    )?)?;
    assert_eq!(manifest["member_count"], 2);
    assert_eq!(manifest["declaration_count"], 2);
    assert_eq!(manifest["row_count"], 2);
    Ok(())
}
use chrono::{DateTime, NaiveDate, Utc};
use serde_json::{Value, json};

use super::{ApiError, decode_declaration};
use crate::domain::models::declaration_ingestion::CapturedDeclaration;

fn fetched_at() -> DateTime<Utc> {
    DateTime::from_timestamp(1_790_985_600, 123_000_000).unwrap()
}

fn source(fields: &Value) -> Value {
    json!({
        "id": 42,
        "parentInterestId": null,
        "category": {"id": 3, "name": "Donations", "type": "Commons"},
        "registrant": {"type": "Member", "memberDetail": {"id": 4613}},
        "versions": [{
            "register": {"id": 820, "publishedDate": "2026-09-07", "type": "Commons"},
            "registrationDate": "2026-09-01",
            "fields": fields
        }]
    })
}

fn decode(source: &Value) -> Result<CapturedDeclaration, ApiError> {
    decode_declaration(source.clone(), fetched_at())
}

#[test]
fn preserves_every_version_and_the_complete_source_payload() {
    let mut source = source(&json!([]));
    source["parentInterestId"] = json!(41);
    source["unprojectedEvidence"] = json!({"notes": ["keep this", null]});
    let mut older_version = source["versions"][0].clone();
    older_version["register"]["id"] = json!(810);
    older_version["register"]["publishedDate"] = json!("2026-08-01");
    older_version["registrationDate"] = Value::Null;
    source["versions"]
        .as_array_mut()
        .unwrap()
        .push(older_version);
    let declaration = decode(&source).unwrap();

    assert_eq!(declaration.id().value(), 42);
    assert_eq!(declaration.parent_id().unwrap().value(), 41);
    assert_eq!(declaration.category_id(), 3);
    assert_eq!(declaration.category_name(), "Donations");
    assert_eq!(declaration.fetched_at(), fetched_at());
    assert_eq!(
        serde_json::from_str::<Value>(declaration.source_json()).unwrap(),
        source
    );
    let [latest, older] = declaration.versions() else {
        panic!("expected both source versions")
    };
    assert_eq!(latest.index(), 0);
    assert_eq!(latest.register_id(), 820);
    assert_eq!(
        latest.published_date(),
        NaiveDate::from_ymd_opt(2026, 9, 7).unwrap()
    );
    assert_eq!(
        latest.registration_date(),
        NaiveDate::from_ymd_opt(2026, 9, 1)
    );
    assert_eq!(older.index(), 1);
    assert_eq!(older.register_id(), 810);
    assert_eq!(
        older.published_date(),
        NaiveDate::from_ymd_opt(2026, 8, 1).unwrap()
    );
    assert_eq!(older.registration_date(), None);
    assert_eq!(latest.groups()[0].path(), "/versions/0/fields");
    assert_eq!(older.groups()[0].path(), "/versions/1/fields");
}

#[test]
fn keeps_repeated_donor_groups_separate_without_inheriting_other_groups_fields() {
    let repeated_donor = json!([
        {"name": "Name", "value": "Alice Example"},
        {"name": "Value", "value": "120.50", "typeInfo": {"currencyCode": "EUR"}}
    ]);
    let declaration = decode(&source(&json!([
        {"name": "DonorName", "value": "Top-level donor"},
        {"name": "PaymentType", "value": "Monetary"},
        {"name": "DonorStatus", "value": "Company"},
        {"name": "DonorCompanyIdentifier", "value": "00001234"},
        {"name": "Donors", "values": [repeated_donor.clone(), repeated_donor, [
            {"name": "Name", "value": "Bob Example"},
            {"name": "Value", "value": "300.00", "typeInfo": {"currencyCode": "GBP"}},
            {"name": "PaymentType", "value": "In kind"}
        ]]}
    ])))
    .unwrap();

    let [top, first_alice, second_alice, bob] = declaration.versions()[0].groups() else {
        panic!("expected a top-level row and all three donor groups")
    };
    assert_eq!(top.donor_name(), Some("Top-level donor"));
    assert_eq!(top.amount(), None);
    assert_eq!(top.currency(), None);
    for alice in [first_alice, second_alice] {
        assert_eq!(alice.donor_name(), Some("Alice Example"));
        assert_eq!(alice.amount(), Some("120.50"));
        assert_eq!(alice.currency(), Some("EUR"));
        assert_eq!(alice.payment_type(), None);
        assert_eq!(alice.funder_kind(), None);
        assert_eq!(alice.company_number(), None);
    }
    assert_eq!(first_alice.path(), "/versions/0/fields/4/values/0");
    assert_eq!(second_alice.path(), "/versions/0/fields/4/values/1");
    assert_eq!(bob.path(), "/versions/0/fields/4/values/2");
    assert_eq!(bob.donor_name(), Some("Bob Example"));
    assert_eq!(bob.amount(), Some("300.00"));
    assert_eq!(bob.currency(), Some("GBP"));
    assert_eq!(bob.payment_type(), Some("In kind"));
}

#[test]
fn preserves_names_attribution_evidence_and_exact_numeric_amounts() {
    let amount: Value = serde_json::from_str(
        r#"{"name":"Value","value":12345678901234567890.1234500,"typeInfo":{"currencyCode":"GBP"}}"#,
    ).unwrap();
    let declaration = decode(&source(&json!([
        {"name": "UltimatePayerName", "value": " Ultimate Payer LTD. "},
        {"name": "DonorName", "value": "Donor Limited"},
        {"name": "PayerName", "value": "Payment Intermediary"},
        {"name": "IsUltimatePayerDifferent", "value": true},
        {"name": "PaymentType", "value": "In kind"},
        {"name": "DonorStatus", "value": "Other"},
        {"name": "DonorCompanyIdentifier", "value": "SC001234"},
        amount
    ])))
    .unwrap();

    let group = &declaration.versions()[0].groups()[0];
    assert_eq!(group.ultimate_payer_name(), Some(" Ultimate Payer LTD. "));
    assert_eq!(group.donor_name(), Some("Donor Limited"));
    assert_eq!(group.payer_name(), Some("Payment Intermediary"));
    assert_eq!(group.is_ultimate_payer_different(), Some(true));
    assert_eq!(group.payment_type(), Some("In kind"));
    assert_eq!(group.funder_kind(), Some("Other"));
    assert_eq!(group.company_number(), Some("SC001234"));
    assert_eq!(group.amount(), Some("12345678901234567890.1234500"));
    assert_eq!(group.currency(), Some("GBP"));
}

#[test]
fn retains_nonfinancial_declarations_and_missing_values() {
    for fields in [
        Value::Null,
        json!([]),
        json!([
            {"name": "Description", "value": "Unpaid trustee"},
            {"name": "Value", "value": null},
            {"name": "DonorName", "value": null}
        ]),
    ] {
        let declaration = decode(&source(&fields)).unwrap();
        let [group] = declaration.versions()[0].groups() else {
            panic!("expected a top-level row")
        };
        assert_eq!(group.path(), "/versions/0/fields");
        assert_eq!(group.ultimate_payer_name(), None);
        assert_eq!(group.donor_name(), None);
        assert_eq!(group.payer_name(), None);
        assert_eq!(group.amount(), None);
        assert_eq!(group.currency(), None);
        assert_eq!(group.payment_type(), None);
        assert_eq!(group.funder_kind(), None);
        assert_eq!(group.company_number(), None);
        assert_eq!(group.is_ultimate_payer_different(), None);
    }
}
use std::{
    fs::{self, File},
    path::Path,
};

use arrow::json::ArrayWriter;
use exposed::domain::models::entity_ingestion::IngestionKey;
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde::Deserialize;

/// The saved funding details that will feed the member and funder views.
#[derive(Debug, Deserialize, PartialEq, Eq)]
pub struct DeclarationFunding {
    pub declaration_id: u32,
    pub member_id: String,
    pub donor_name: Option<String>,
    pub amount: Option<String>,
    pub currency: Option<String>,
    pub payment_type: Option<String>,
    pub funder_kind: Option<String>,
    pub company_number: Option<String>,
}

pub fn read_declaration_funding(
    data_dir: &Path,
    key: &IngestionKey,
) -> anyhow::Result<Vec<DeclarationFunding>> {
    let directory = data_dir.join(key.to_string()).join("raw/declarations");
    let mut json = ArrayWriter::new(Vec::new());
    for entry in fs::read_dir(directory)? {
        let path = entry?.path();
        if path
            .extension()
            .is_some_and(|extension| extension == "parquet")
        {
            let reader = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
            let columns = [
                "declaration_id",
                "member_id",
                "donor_name",
                "amount",
                "currency",
                "payment_type",
                "funder_kind",
                "company_number",
            ]
            .into_iter()
            .map(|name| reader.schema().index_of(name))
            .collect::<Result<Vec<_>, _>>()?;
            for batch in reader.build()? {
                json.write(&batch?.project(&columns)?)?;
            }
        }
    }
    json.finish()?;
    Ok(serde_json::from_slice(&json.into_inner())?)
}
# exposed

Where do MPs get their money from?

Imports everyone who has served in the Commons during the configured Parliament and their available declarations into PostgreSQL. Declarations store parsed fields and extracted funding for later display.

The planned journalist-facing research application is described in the
[backend product specification](docs/specs/journalist-research-backend.md).

## Getting started

Requires Python **3.14+**, Docker Compose, a Rust toolchain and
[SQLx CLI](https://github.com/launchbadge/sqlx/tree/v0.9.0/sqlx-cli) **0.9.0**
(matching the Rust workspace). Install the PostgreSQL CLI with:

```sh
cargo install sqlx-cli --version 0.9.0 --no-default-features --features rustls,postgres,sqlx-toml
```

Run commands from the repository root:

```sh
python3.14 -m venv ingest/.venv
ingest/.venv/bin/python -m pip install -r ingest/requirements.lock
ingest/.venv/bin/python -m pip install --no-deps -e ./ingest
test -f ingest/.env || cp ingest/.env.example ingest/.env
make db-start
make db-migrate
make import-members
make import-declarations
```

Setup creates `ingest/.env` only when absent. The Makefile runs SQLx from `ingest/`
so it and the importer use that file; existing environment variables take
precedence. The example URL targets local PostgreSQL and explicitly disables TLS
for that loopback connection. Use the appropriate TLS setting for a hosted database.

The schema uses a single development baseline. See the
[migration instructions](db/README.md) before adopting SQLx on an existing dbmate
database or editing the baseline. See the
[funder identification rules](ingest/README.md#funder-identification) for imported funding.

## Capture declarations with the Rust CLI

Once members are loaded into PostgreSQL, capture their available Commons
declarations with:

```sh
cargo run -- data declarations fetch exposed/config/declarations-dev.yaml
```

The configuration supplies `connection_string`, `data_dir`, and a nonzero
`batch_size`. The command reads all stored members, including former MPs, once
at startup. An empty cohort returns an instruction to load members first. The
existing `data members fetch` and `data members load` commands remain available.
To choose the run identity, append `--ingestion-key <UUID>`; otherwise a new key
is generated for the output directory. The completion manifest contains the run
identity and counts.

Each run writes one logical dataset at
`<data_dir>/<ingestion_key>/raw/declarations/`, partitioned into
`<database-member-UUID>.parquet` files. Members without declarations receive a
valid empty file. `manifest.json` identifies the completed run, every selected
member and file, and separate declaration and flattened-row counts. A directory
without this manifest is incomplete. Existing declaration output is protected;
retry a failed run with a new ingestion key.

The dataset retains expired interests, all returned versions, nonfinancial
declarations, and parent references as supplied by the API. Every version has a
top-level row plus a row for each nested `Donors` group, identified by `version_index` and
the `source_field_path` JSON pointer. Names, exact amount text, currency, payment
type, donor status, company identifiers, and ultimate-payer flags stay within
their original source groups. Missing optional values remain null. Calendar
dates use Parquet dates, and `fetched_at` is a UTC timestamp. Complete original
`source_json`, including unprojected fields, is repeated on the declaration's rows.
Each member file records that MP's association with the returned declarations.
The same declaration ID can appear in several member files. The manifest counts
these MP associations as separate declarations.

The declaration-fetch service reads the stored cohort and saves each member's
complete API response. The Parliament adapter owns requests, pagination and JSON
deserialization; the PostgreSQL adapter owns the member query; and the filesystem
adapter owns Parquet and file publication. Each page is requested once, and
request or parsing errors propagate to the caller. Once pagination is exhausted,
the response is treated as complete for that MP. Parent references stay in the
saved data without further API requests. Cleaning, version selection, attribution,
funder resolution and database publication are later steps that use the saved data.

Run the Rust checks with a migrated PostgreSQL database available through
`DATABASE_URL` (the root `.env` is also supported). Integration tests require
access to Parliament's live APIs; the existing search test uses the preloaded
database configured in `exposed/config/server-test.yaml`.

```sh
cargo fmt --all -- --check
cargo check --all-targets
cargo clippy --all-targets -- -D warnings
cargo test
```

## Develop the application with Docker Compose

Initialize the database using the setup above before starting the app. SQLx checks
queries against the live schema during compilation, so a fresh database needs
`make db-migrate` first. Migrations remain an explicit step.

```sh
docker compose up --build
```

Open the Svelte frontend at **http://localhost:5173**. It searches the existing
API as you type, shows MPs and funders together in the API's similarity order,
and preserves the names returned by the source. Enter at least three characters;
press `/` to focus search and Escape to clear it. A query URL such as
`http://localhost:5173/?q=HSBC` can be shared for manual testing.

The API listens at `http://localhost:6999`. For example:

```sh
curl 'http://localhost:6999/search?term=McDonald&max_entries=10'
```

The repository is bind-mounted into the container. `cargo watch` rebuilds and
restarts the app when Rust source, Cargo manifests, `Cargo.lock`, or files in
`exposed/config/` change. Polling detects edits through Docker Desktop bind mounts.
The first image and app builds take longer; named volumes cache Cargo downloads
and Linux build artifacts separately from the host's `target/` directory.

The container uses `exposed/config/compose.yaml` and connects to `postgres:5432`.
Its `DATABASE_URL` supplies the same connection for SQLx compile-time checks.
For running Cargo on the host, `exposed/config/dev.yaml` uses `localhost:55432`.

The frontend service proxies `/api/search` to `http://exposed:6999/search`.
Its source is bind-mounted, with polling for live reload on Docker Desktop and a
separate Linux dependency volume. Restart `frontend` after changing its package
manifest or lockfile; dependencies are refreshed at startup. The API may take
longer than the frontend to compile on a first run; use **Try again** if search
is not ready yet.

Use `docker compose stop frontend exposed` to stop the app and keep the caches.
`make db-start` and `make db-stop` control only PostgreSQL.

The Compose project is named `exposed`. When testing a frontend-only change in a
worktree against an already running API, use
`docker compose up --build -d --no-deps frontend` to avoid recreating the backend
and database from that worktree. This serves the frontend from the worktree.

### Frontend development and checks

To run the frontend on the host instead of Docker, use Node.js **24+**:

```sh
cd frontend
npm ci
npm run dev
```

The host dev server proxies to `http://127.0.0.1:6999` by default. Override
`EXPOSED_API_ORIGIN` when starting Vite to use another backend. This setting is
server-side; the browser always uses the same-origin `/api/search` path.
The frontend image is for local development. `npm run build` produces static
assets in `frontend/dist`; a production host must also route `/api/search` to
the Rust API.

The similarity threshold slider refreshes results automatically: lower values
include broader matches, from 0 to 1 in steps of 0.01 (default 1). The search URL
preserves the query and threshold, for example `/?q=John&strictness=0.65`.
Search delay, result limits and defaults live in
[`frontend/src/lib/search.ts`](frontend/src/lib/search.ts). The API caps each entity type separately, so the UI describes the returned
results without claiming a total count or offering unsupported pagination.
This slice displays results; entity pages and in-app feedback collection are
future work. Feedback is gathered through manual testing.

For frontend checks, install dependencies and the browser once, then run:

```sh
npm --prefix frontend ci
cd frontend && PLAYWRIGHT_BROWSERS_PATH=0 npx playwright install chromium && cd ..
make frontend-check
```

Browser tests use a controlled API to check ranking, request cancellation,
empty/error recovery, text escaping and narrow layouts. For manual verification,
try an MP's name, `HSBC`, a misspelling, clearing a pending query, and stopping
the API to check retry behavior. See the
[search design brief](docs/design/entity-search.md) for the agreed scope.

## View example declarations from the API

These standalone scripts require `bash`, `curl` and `jq`; no database, API key or
Python setup is needed. Run from the repository root:

```sh
./scripts/view-individual-declaration.sh
./scripts/view-legal-entity-declaration.sh
# View the complete API response, including all returned fields and versions:
./scripts/view-individual-declaration.sh --raw
./scripts/view-legal-entity-declaration.sh --raw
```

The scripts fetch fixed examples directly from Parliament on each run and print
formatted JSON. The default view selects the version with the latest register
publication date and includes the MP, donor, donor status, amount, currency,
company number and how the support was received. Amounts remain decimal strings.

Examples verified on 20 September 2026:

| Script | Declaration | Source donor status | Support |
| --- | --- | --- | --- |
| Individual | [16901](https://interests-api.parliament.uk/api/v2/Interests/16901), Alex Burghart | Individual | David Robert Meller, GBP 2,000 |
| Legal entity | [16863](https://interests-api.parliament.uk/api/v2/Interests/16863), Dr Simon Opher | Company | Labour Together Limited (09630980), GBP 5,000 |

Both examples record support linked to the MP but received by a party organisation,
rather than a direct personal payment. The legal-entity example uses the API's
explicit `Company` status. These are illustrative records, not searches for every
individual or legal entity. Upstream records can change; the default view fails
if the expected donor status changes, and `--raw` lets you inspect the response.

Contains Parliamentary information licensed under the
[Open Parliament Licence v3.0](https://www.parliament.uk/site-information/copyright-parliament/open-parliament-licence/).

## Useful commands

| Command | Purpose |
| --- | --- |
| `make db-migrate` | Apply the development schema baseline |
| `make db-revert` | Revert the baseline, deleting its tables and data |
| `make db-migration-status` | Show SQLx migration status |
| `make db-nuke` | Delete the configured database and recreate it from the baseline |
| `make import-members` | Refresh member data |
| `make import-declarations` | Refresh declarations for the stored member cohort |
| `make verify` | Check data in the local Compose database |
| `make check` | Run importer lint, formatting checks, type checks and tests |
| `make frontend-dev` | Start the Svelte frontend and API with live reload |
| `make frontend-check` | Check, build and browser-test the frontend |
| `make test-unit` | Run tests without PostgreSQL |
| `make format` | Format Python files |
| `make db-stop` | Stop local PostgreSQL while retaining data |

`make test` and `make check` require local PostgreSQL (`make db-start`). Tests create and remove their own temporary databases. Override `EXPOSED_TEST_ADMIN_DSN` with a PostgreSQL URL to use a different test server; it must allow database creation. `SQLX` can also be overridden with an absolute SQLx CLI executable path.

See the [importer documentation](ingest/README.md) for configuration, data rules and refresh behavior.

