//! Parquet partitions and completion manifests for raw declaration captures.

use std::{
    path::{Path, PathBuf},
    sync::Arc,
};

use arrow::{
    datatypes::{DataType, Field, Schema, TimeUnit},
    json::ReaderBuilder,
};
use chrono::Utc;
use parquet::arrow::async_writer::AsyncArrowWriter;
use serde::Serialize;
use serde_json::{Value, json};
