    ].into());
    Schema::new(vec![
        Field::new("member_id", DataType::Utf8, false),
        Field::new("parliament_member_id", DataType::UInt32, false),
        Field::new("declaration_id", DataType::UInt32, false),
        Field::new("parent_declaration_id", DataType::UInt32, true),
