async fn saves_one_record_per_mp_with_nested_funding_entries() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let storage = ExposedDataPipeline::new_with_ingestion_key(
        &tmp.path().to_path_buf(), IngestionKey::default(),
    )?;
