use std::sync::Arc;

use arrow::array::{RecordBatch, StringArray, UInt32Array};
use itertools::izip;
use parquet::arrow::{ParquetRecordBatchStreamBuilder, async_writer::AsyncArrowWriter};

use crate::{
    domain::{
        models::{
            declaration_ingestion::{CapturedDeclaration, MemberAsId},
            entity_ingestion::IngestionKey,
            parliament_member::ParliamentMember,
        },
        repositories::entity_ingestion::{EntityIngestionStorage, EntitySearchPipelineError},
    },
    outbound::file_system::{ExposedDataPipeline, members_schema},
};
use futures::TryStreamExt;

impl EntityIngestionStorage for ExposedDataPipeline {
    async fn write_raw_declarations(
        &self,
        member: MemberAsId,
        declarations: &[CapturedDeclaration],
    ) -> Result<(), EntitySearchPipelineError> {
        self.write_declaration_partition(member, declarations).await
    }

    fn ingestion_key(&self) -> IngestionKey {
        self.key().into()
    }
    async fn read_raw_members(&self) -> Result<Vec<ParliamentMember>, EntitySearchPipelineError> {
        let read_from = tokio::fs::File::open(self.raw_path().join("members.parquet"))
            .await
            .map_err(|e| {
                EntitySearchPipelineError::ReadError(format!("cannot read raw members file:{e}"))
            })?;

        let stream = ParquetRecordBatchStreamBuilder::new(read_from)
            .await
            .map_err(|e| {
                EntitySearchPipelineError::ReadError(format!("cannot read raw members file:{e}"))
            })?
            .build()
            .map_err(|e| {
                EntitySearchPipelineError::ReadError(format!("cannot read raw members file:{e}"))
            })?;

        let results = stream.try_collect::<Vec<_>>().await.unwrap();
        let first_batch = results.first().ok_or_else(|| {
            EntitySearchPipelineError::ReadError("must be a read result for members".to_string())
        })?;
        let ids: Vec<_> = first_batch
            .column(0)
            .as_any()
            .downcast_ref::<UInt32Array>()
            .ok_or_else(|| EntitySearchPipelineError::ReadError("cannot cast ids".to_string()))?
            .into_iter()
            .map(|v| v.unwrap())
            .collect();

        let names: Vec<_> = first_batch
            .column(1)
            .as_any()
            .downcast_ref::<StringArray>()
            .ok_or_else(|| EntitySearchPipelineError::ReadError("cannot cast names".to_string()))?
            .into_iter()
            .map(|v| v.unwrap())
            .collect();

        let party_ids: Vec<_> = first_batch
            .column(2)
            .as_any()
            .downcast_ref::<UInt32Array>()
            .ok_or_else(|| {
                EntitySearchPipelineError::ReadError("cannot cast party ids".to_string())
            })?
            .into_iter()
            .map(|v| v.unwrap())
            .collect();

        let parties: Vec<_> = first_batch
            .column(3)
            .as_any()
            .downcast_ref::<StringArray>()
            .ok_or_else(|| EntitySearchPipelineError::ReadError("cannot cast parties".to_string()))?
            .into_iter()
            .map(|v| v.unwrap())
            .collect();

        let constituencies: Vec<_> = first_batch
            .column(4)
            .as_any()
            .downcast_ref::<StringArray>()
            .ok_or_else(|| {
                EntitySearchPipelineError::ReadError("cannot cast constituencies".to_string())
            })?
            .into_iter()
            .map(|v| v.unwrap())
            .collect();

        let mut members = Vec::with_capacity(names.len());
        for (pmi, n, pi, pn, c) in izip!(ids, names, party_ids, parties, constituencies) {
            members.push(ParliamentMember::new(
                n.to_string(),
                pmi,
                pn.to_string(),
                pi,
                c.to_string(),
            ));
        }

        Ok(members)
    }
    async fn read_cleaned_data(&self) -> Result<(), EntitySearchPipelineError> {
        let _ = tokio::spawn(async {}).await;
        Ok(())
    }
    async fn read_resolved_data(&self) -> Result<(), EntitySearchPipelineError> {
        let _ = tokio::spawn(async {}).await;
        Ok(())
    }
    async fn write_raw_members(
        &self,
        members: &[ParliamentMember],
    ) -> Result<(), EntitySearchPipelineError> {
        let write_to = tokio::fs::File::create_new(self.raw_path().join("members.parquet"))
            .await
            .map_err(|e| {
                EntitySearchPipelineError::WriteError(format!("cannot create raw members file:{e}"))
            })?;

        let schema = Arc::new(members_schema());

        let (mut pmi, mut n, mut pi, mut pn, mut c) = (vec![], vec![], vec![], vec![], vec![]);
        for m in members {
            pmi.push(m.member_id());
            n.push(m.name());
            pi.push(m.party_id());
            pn.push(m.party_name());
            c.push(m.constituency());
        }

        let (pmi, n, pi, pn, c) = (
            UInt32Array::from(pmi),
            StringArray::from(n),
            UInt32Array::from(pi),
            StringArray::from(pn),
            StringArray::from(c),
        );

        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(pmi),
                Arc::new(n),
                Arc::new(pi),
                Arc::new(pn),
                Arc::new(c),
            ],
        )
        .map_err(|e| {
            EntitySearchPipelineError::WriteError(format!("cannot create write batch: {e}"))
        })?;

        let mut writer = AsyncArrowWriter::try_new(write_to, schema, None).map_err(|e| {
            EntitySearchPipelineError::WriteError(format!("cannot create writer:{e}"))
        })?;

        writer.write(&batch).await.map_err(|e| {
            EntitySearchPipelineError::WriteError(format!("cannot write to buffer:{e}"))
        })?;

        writer.close().await.map_err(|e| {
            EntitySearchPipelineError::WriteError(format!("cannot flush writer:{e}"))
        })?;

        Ok(())
    }
    async fn write_cleaned_data(&self) -> Result<(), EntitySearchPipelineError> {
        let _ = tokio::spawn(async {}).await;
        Ok(())
    }
    async fn write_resolved_data(&self) -> Result<(), EntitySearchPipelineError> {
        let _ = tokio::spawn(async {}).await;
        Ok(())
    }
}
//! File system interface for entity search ingestion

use std::path::{self, PathBuf};

use arrow::datatypes::{DataType, Field, Schema};
use uuid::Uuid;

use crate::domain::{
    models::entity_ingestion::IngestionKey,
    repositories::entity_ingestion::EntitySearchPipelineError,
};

/// File system pipeline
#[derive(Clone)]
pub struct ExposedDataPipeline {
    root: PathBuf,
    key: PipelineKey,
    fs_schema: FsSchema,
}

#[derive(Clone)]
pub struct PipelineKey(Uuid);

impl PipelineKey {
    pub fn new() -> Self {
        Self(Uuid::now_v7())
    }
}

impl From<&PipelineKey> for IngestionKey {
    fn from(value: &PipelineKey) -> Self {
        Self::new(value.0)
    }
}

impl From<IngestionKey> for PipelineKey {
    fn from(value: IngestionKey) -> Self {
        Self(value.uuid())
    }
}

#[derive(Clone)]
struct FsSchema {
    raw: String,
    // cleaned: String,
    // resolved: String,
}

impl Default for FsSchema {
    fn default() -> Self {
        Self {
            raw: "raw".into(),
            // cleaned: "cleaned".into(),
            // resolved: "resolved".into(),
        }
    }
}

impl ExposedDataPipeline {
    /// Creates a new instance of [`ExposedDataPipeline`] with an [`IngestionKey`]
    ///
    /// # Errors
    /// - if [`root`] cannot be parsed as absolute
    /// - if required directories cannot be created
    pub fn new_with_ingestion_key(
        root: &PathBuf,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let root_abs = path::absolute(root).map_err(|_| {
            EntitySearchPipelineError::Unexpected("valid root path must be provided".to_string())
        })?;

        let res = Self {
            root: root_abs,
            key: PipelineKey::from(key),
            fs_schema: FsSchema::default(),
        };
        std::fs::create_dir_all(res.raw_path()).map_err(|_| {
            EntitySearchPipelineError::Unexpected("must be able to create fs paths".to_string())
        })?;
        Ok(res)
    }

    fn latest_run_path(&self) -> PathBuf {
        self.root.join(self.key.0.to_string())
    }

    pub(super) fn raw_path(&self) -> PathBuf {
        self.latest_run_path().join(&self.fs_schema.raw)
    }

    pub(super) const fn key(&self) -> &PipelineKey {
        &self.key
    }

    // pub(super) fn cleaned_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.cleaned)
    // }
    //
    // pub(super) fn resolved_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.resolved)
    // }
}

pub(super) fn members_schema() -> Schema {
    let pmi = Field::new("parliament_member_id", DataType::UInt32, false);
    let n = Field::new("name", DataType::Utf8, false);
    let pi = Field::new("party_id", DataType::UInt32, false);
    let pn = Field::new("party_name", DataType::Utf8, false);
    let c = Field::new("constituency", DataType::Utf8, false);
    Schema::new(vec![pmi, n, pi, pn, c])
}
//! Parquet storage for captured declarations.

use std::{path::PathBuf, sync::Arc};

use arrow::{
    datatypes::{DataType, Field, Schema, TimeUnit},
    json::ReaderBuilder,
};
use chrono::{DateTime, NaiveDate, Utc};
use parquet::arrow::async_writer::AsyncArrowWriter;
use serde::Serialize;
use tokio::fs;

use super::file_system::ExposedDataPipeline;
use crate::domain::{
    models::declaration_ingestion::{
        CapturedDeclaration, CapturedFundingEntry, DeclarationId, MemberAsId,
    },
    repositories::entity_ingestion::EntitySearchPipelineError,
};

#[cfg(test)]
mod tests;

impl ExposedDataPipeline {
    fn declarations_path(&self) -> PathBuf {
        self.raw_path().join("declarations")
    }

    pub(super) async fn write_declaration_partition(
        &self,
        member: MemberAsId,
        declarations: &[CapturedDeclaration],
    ) -> Result<(), EntitySearchPipelineError> {
        let directory = self.declarations_path();
        fs::create_dir_all(&directory).await.map_err(write_error)?;
        let file = fs::File::create_new(directory.join(member_filename(member)))
            .await
            .map_err(write_error)?;
        let schema = Arc::new(declarations_schema());
        let mut writer =
            AsyncArrowWriter::try_new(file, schema.clone(), None).map_err(write_error)?;
        let records = declarations
            .iter()
            .map(|declaration| declaration_record(member, declaration))
            .collect::<Vec<_>>();
        let mut decoder = ReaderBuilder::new(schema)
            .build_decoder()
            .map_err(write_error)?;
        decoder.serialize(&records).map_err(write_error)?;
        if let Some(batch) = decoder.flush().map_err(write_error)? {
            writer.write(&batch).await.map_err(write_error)?;
        }
        writer.close().await.map_err(write_error)?;
        Ok(())
    }
}

fn member_filename(member: MemberAsId) -> String {
    format!("{}.parquet", member.member_id())
}

fn write_error(error: impl std::fmt::Display) -> EntitySearchPipelineError {
    EntitySearchPipelineError::WriteError(error.to_string())
}

fn declarations_schema() -> Schema {
    let funding_entry = DataType::Struct(
        vec![
            Field::new("ultimate_payer_name", DataType::Utf8, true),
            Field::new("donor_name", DataType::Utf8, true),
            Field::new("payer_name", DataType::Utf8, true),
            Field::new("amount", DataType::Utf8, true),
            Field::new("currency", DataType::Utf8, true),
            Field::new("payment_type", DataType::Utf8, true),
            Field::new("funder_kind", DataType::Utf8, true),
            Field::new("company_number", DataType::Utf8, true),
            Field::new("is_ultimate_payer_different", DataType::Boolean, true),
        ]
        .into(),
    );
    Schema::new(vec![
        Field::new("member_id", DataType::Utf8, false),
        Field::new("parliament_member_id", DataType::UInt32, false),
        Field::new("declaration_id", DataType::UInt32, false),
        Field::new("parent_declaration_id", DataType::UInt32, true),
        Field::new("category_id", DataType::UInt32, false),
        Field::new("category_name", DataType::Utf8, false),
        Field::new("register_id", DataType::UInt32, false),
        Field::new("register_published_date", DataType::Date32, false),
        Field::new("registration_date", DataType::Date32, true),
        Field::new_list(
            "funding_entries",
            Field::new("item", funding_entry, false),
            false,
        ),
        Field::new(
            "fetched_at",
            DataType::Timestamp(TimeUnit::Microsecond, Some("+00:00".into())),
            false,
        ),
        Field::new("source_json", DataType::Utf8, false),
    ])
}

#[derive(Serialize)]
struct DeclarationRecord<'a> {
    member_id: String,
    parliament_member_id: u32,
    declaration_id: u32,
    parent_declaration_id: Option<u32>,
    category_id: u32,
    category_name: &'a str,
    register_id: u32,
    register_published_date: NaiveDate,
    registration_date: Option<NaiveDate>,
    funding_entries: &'a [CapturedFundingEntry],
    fetched_at: DateTime<Utc>,
    source_json: &'a str,
}

fn declaration_record(
    member: MemberAsId,
    declaration: &CapturedDeclaration,
) -> DeclarationRecord<'_> {
    DeclarationRecord {
        member_id: member.member_id().to_string(),
        parliament_member_id: member.parliament_member_id(),
        declaration_id: declaration.id().value(),
        parent_declaration_id: declaration.parent_id().map(DeclarationId::value),
        category_id: declaration.category_id(),
        category_name: declaration.category_name(),
        register_id: declaration.register_id(),
        register_published_date: declaration.register_published_date(),
        registration_date: declaration.registration_date(),
        funding_entries: declaration.funding_entries(),
        fetched_at: declaration.fetched_at(),
        source_json: declaration.source_json(),
    }
}

